from notekeep.tags import with_tag


def test_with_tag_keeps_matching_notes_in_order():
    notes = [
        {"id": 1, "text": "a", "tags": ["x"]},
        {"id": 2, "text": "b", "tags": ["y"]},
        {"id": 3, "text": "c", "tags": ["y", "x"]},
    ]
    assert [n["id"] for n in with_tag(notes, "x")] == [1, 3]


def test_with_tag_note_without_tags_key_matches_nothing():
    assert with_tag([{"id": 1, "text": "a"}], "x") == []

